## Key Concepts
- Data lineage across KDS, Fargate, and S3
- Immutable raw storage and audit tracking
- Idempotent writes and failure handling
- Observability via CloudWatch and Athena

## Code Example
```javascript
// Minimal conditional put to DynamoDB to upsert audit records
const { DynamoDBClient, PutItemCommand } = require('@aws-sdk/client-dynamodb');
const client = new DynamoDBClient({region: 'us-east-1'});
const cmd = new PutItemCommand({
  TableName: 'TelemetryAudit',
  Item: {
    event_id: { S: id },
    shard_id: { S: shard },
    ingest_ts: { N: String(ingest) },
    process_ts: { N: String(now) },
    status: { S: 'OK' },
    transformations_hash: { S: hash }
  },
  ConditionExpression: 'attribute_not_exists(event_id)'
});
await client.send(cmd);
```

